	allowed_destination_addresses: string[] | undefined;
	allowed_sender_addresses: string[] | undefined;
	MINIFLARE_EMAIL_DISK_SYSTEM: Fetcher;
	MINIFLARE_EMAIL_DISK_PROJECT?: Fetcher;
