"use server";

import { serverAction } from "rwsdk/worker";
import { drizzle } from "drizzle-orm/d1";
import { env } from "cloudflare:workers";
import { eq } from "drizzle-orm";
import * as schema from "../../db/schema";

export const incrementLike = serverAction(async () => {
  const db = drizzle(env.DB, { schema });
  const result = await db.select().from(schema.likes).execute();
  if (result.length > 0) {
    const row = result[0];
    await db
      .update(schema.likes)
      .set({ count: row.count + 1 })
      .where(eq(schema.likes.id, row.id))
      .execute();
  } else {
    await db.insert(schema.likes).values({ count: 1 }).execute();
  }
});

"use client";

import React, { useTransition } from "react";
import { incrementLike } from "./actions";

interface LikeButtonProps {
  initialCount: number;
}

export const LikeButton: React.FC<LikeButtonProps> = ({ initialCount }) => {
  const [isPending, startTransition] = useTransition();

  const handleLike = () => {
    startTransition(async () => {
      await incrementLike();
    });
  };

  return (
    <div style={{ padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1>Persistent Like Button</h1>
      <p>
        Likes: <span data-testid="like-count">{initialCount}</span>
      </p>
      <button
        data-testid="like-button"
        onClick={handleLike}
        disabled={isPending}
        style={{
          padding: "10px 20px",
          fontSize: "16px",
          cursor: "pointer",
          backgroundColor: "#0070f3",
          color: "white",
          border: "none",
          borderRadius: "5px",
        }}
      >
        {isPending ? "Liking..." : "Like"}
      </button>
    </div>
  );
};

import { drizzle } from "drizzle-orm/d1";
import { env } from "cloudflare:workers";
import * as schema from "../../db/schema";
import { LikeButton } from "./LikeButton";

export const Home = async () => {
  const db = drizzle(env.DB, { schema });
  const result = await db.select().from(schema.likes).execute();
  const count = result[0]?.count ?? 0;

  return <LikeButton initialCount={count} />;
};
